<section class="section"><x-heading title="Daftar Pengguna"><button class="button" data-open="user-new" type="button">{{ \App\Support\Ui::icon('plus') }}Tambah Pengguna</button></x-heading><x-table :headers="['ID','Nama','Username','Email','Role','No. Telepon','Aksi']" :empty="$users->isEmpty()">@foreach($users as $u)<tr><td class="record-id">{{ \App\Support\Ui::code('USR',$u->id_user) }}</td><td class="record-name">{{ $u->nama }}</td><td>{{ $u->username }}</td><td>{{ $u->email }}</td><td><span class="badge {{ $u->role==='admin'?'red':($u->role==='petani'?'green':'') }}">{{ ucfirst($u->role) }}</span></td><td>{{ $u->no_telepon?:'—' }}</td><td>@if($u->id_user===auth()->id())<button class="icon-button" type="button" data-open="user-{{ $u->id_user }}" aria-label="Edit {{ $u->nama }}">{{ \App\Support\Ui::icon('edit') }}</button>@else<x-actions :edit="'user-'.$u->id_user" :delete="route('admin.users.destroy',$u->id_user)" :name="$u->nama.' (nonaktifkan akun)'"/>@endif</td></tr>@endforeach</x-table></section>
